function fitsShortForm(word: string, abbr: string): boolean {
  const tokens = abbr.match(/[a-z]|\d+/g) ?? [];
  let i = 0;
  for (const t of tokens) {
    if (/\d/.test(t)) {
      if (t[0] === "0") return false;
      i += Number(t);
      if (i > word.length) return false;
    } else {
      if (word[i] !== t) return false;
      i++;
    }
  }
  return i === word.length;
}

