import re

class Solution:
    def fitsShortForm(self, word: str, abbr: str) -> bool:
        i = 0
        for t in re.findall(r"[a-z]|\d+", abbr):
            if t.isdigit():
                if t[0] == "0":
                    return False
                i += int(t)
                if i > len(word):
                    return False
            else:
                if i >= len(word) or word[i] != t:
                    return False
                i += 1
        return i == len(word)

