function fitsShortForm(word: string, abbr: string): boolean {
  let i = 0, j = 0;
  while (j < abbr.length) {
    const ch = abbr[j];
    if (ch >= "0" && ch <= "9") {
      if (ch === "0") return false;
      let k = 0;
      while (j < abbr.length && abbr[j] >= "0" && abbr[j] <= "9") {
        k = k * 10 + (abbr.charCodeAt(j) - 48);
        if (k > word.length) return false;
        j++;
      }
      i += k;
      if (i > word.length) return false;
    } else {
      if (i >= word.length || word[i] !== ch) return false;
      i++;
      j++;
    }
  }
  return i === word.length;
}

